<?php
use App\Actions\Donations\ChangeDonationStatus; use App\Actions\Donations\RefundDonation; use App\DonationPaymentStatus; use App\Models\Donation; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Gate; use Livewire\Attributes\Title; use Livewire\Component;
new #[Title('Donation Details')] class extends Component { public Donation $donation; public string $refundAmount=''; public string $refundReason=''; public string $refundReference=''; public function mount():void{Gate::authorize('view',$this->donation);$this->donation->load(['donor','category','campaign','recorder','approver','transactions','refunds.processor']);} public function changeStatus(string $status,ChangeDonationStatus $change):void{$change->handle(Auth::user(),$this->donation,DonationPaymentStatus::from($status));$this->donation->refresh();session()->flash('success',__('Status updated.'));} public function refund(RefundDonation $refund):void{$this->validate(['refundAmount'=>['required','numeric','gt:0'],'refundReason'=>['required','string','max:1000'],'refundReference'=>['nullable','string','max:255','unique:donation_refunds,reference']]);$refund->handle(Auth::user(),$this->donation,$this->refundAmount,$this->refundReason,$this->refundReference?:null);$this->donation->refresh()->load('refunds');$this->reset(['refundAmount','refundReason','refundReference']);session()->flash('success',__('Refund recorded.'));} }; ?>
<div class="mx-auto w-full max-w-6xl space-y-6"><x-admin.page-header :title="$donation->reference" :description="__('Donation record and audit-safe payment workflow.')" :eyebrow="__('Donation details')"><x-slot:actions>@can('update',$donation)<flux:button :href="route('donations.edit',$donation)" wire:navigate>{{__('Edit')}}</flux:button>@endcan @can('printReceipt',$donation)<flux:button :href="route('donations.receipt',$donation)" target="_blank" icon="printer">{{__('Print receipt')}}</flux:button>@endcan</x-slot:actions></x-admin.page-header>
<div class="grid gap-6 lg:grid-cols-3"><section class="space-y-4 rounded-xl border bg-white p-6 lg:col-span-2 dark:border-zinc-800 dark:bg-zinc-900"><div class="grid gap-5 sm:grid-cols-2"><div><p class="text-xs text-slate-500">{{__('Donor')}}</p><p class="font-medium">{{$donation->donorLabel()}}</p>@unless($donation->is_anonymous)<p>{{$donation->donor?->email}}</p><p>{{$donation->donor?->phone}}</p>@endunless</div><div><p class="text-xs text-slate-500">{{__('Receipt')}}</p><p class="font-mono">{{$donation->receipt_number??__('Not issued')}}</p></div><div><p class="text-xs text-slate-500">{{__('Amount')}}</p><p class="text-xl font-semibold">{{$donation->currency}} {{number_format((float)$donation->amount,2)}}</p></div><div><p class="text-xs text-slate-500">{{__('Status')}}</p><flux:badge>{{$donation->payment_status->label()}}</flux:badge></div><div><p class="text-xs text-slate-500">{{__('Category / campaign')}}</p><p>{{$donation->category->name}}</p><p>{{$donation->campaign?->name}}</p></div><div><p class="text-xs text-slate-500">{{__('Payment')}}</p><p>{{$donation->payment_method->label()}}</p><p>{{$donation->transaction_reference}}</p></div><div><p class="text-xs text-slate-500">{{__('Source / date')}}</p><p>{{$donation->source->label()}}</p><p>{{$donation->donated_at->format('M j, Y g:i A')}}</p></div><div><p class="text-xs text-slate-500">{{__('Administration')}}</p><p>{{__('Recorded by')}} {{$donation->recorder?->name??__('System')}}</p><p>{{__('Approved by')}} {{$donation->approver?->name??'—'}}</p></div></div>@if($donation->notes)<div><p class="text-xs text-slate-500">{{__('Notes')}}</p><p class="whitespace-pre-line">{{$donation->notes}}</p></div>@endif @if($donation->internal_notes)<div><p class="text-xs text-slate-500">{{__('Internal notes')}}</p><p class="whitespace-pre-line">{{$donation->internal_notes}}</p></div>@endif</section>
<aside class="space-y-5"><section class="space-y-3 rounded-xl border bg-white p-5 dark:border-zinc-800 dark:bg-zinc-900"><flux:heading>{{__('Workflow')}}</flux:heading>@can('approve',$donation)@foreach([DonationPaymentStatus::Pending,DonationPaymentStatus::Processing,DonationPaymentStatus::Completed,DonationPaymentStatus::Failed,DonationPaymentStatus::Cancelled] as $x)<flux:button wire:click="changeStatus('{{$x->value}}')" size="sm" class="w-full" wire:loading.attr="disabled" wire:target="changeStatus">{{__('Mark :status',['status'=>$x->label()])}}</flux:button>@endforeach@endcan</section>@can('refund',$donation)<form wire:submit="refund" class="space-y-3 rounded-xl border bg-white p-5 dark:border-zinc-800 dark:bg-zinc-900"><flux:heading>{{__('Manual refund')}}</flux:heading><p class="text-xs text-slate-500">{{__('This records a refund; it does not contact a payment provider.')}}</p><flux:input wire:model="refundAmount" type="number" step="0.01" :label="__('Amount')"/><flux:textarea wire:model="refundReason" :label="__('Reason')"/><flux:input wire:model="refundReference" :label="__('Reference')"/><flux:button type="submit" variant="danger" wire:loading.attr="disabled" wire:target="refund">{{__('Record refund')}}</flux:button></form>@endcan</aside></div>
<section class="rounded-xl border bg-white p-6 dark:border-zinc-800 dark:bg-zinc-900"><flux:heading>{{__('Refund history')}}</flux:heading><div class="mt-4 space-y-3">@forelse($donation->refunds as $refund)<div class="flex justify-between border-b pb-3 dark:border-zinc-800"><span>{{$refund->reason}}</span><strong>{{$donation->currency}} {{number_format((float)$refund->amount,2)}}</strong></div>@empty<p class="text-slate-500">{{__('No refunds recorded.')}}</p>@endforelse</div></section></div>
